import { useState, useSyncExternalStore } from "react";

/*
 * Dates for these examples, measured from when they appear. In an app the dates come from your
 * data, and this is not needed.
 */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** A fixed moment for server rendering, so the server and the browser write the same HTML. */
const reference = Date.UTC(2026, 0, 15, 12);

const subscribe = () => () => {
  // Whether the page has hydrated never changes back.
};

const useDemoClock = () => {
  // oxlint-disable-next-line react/hook-use-state -- the time is read once, when the example appears, and never replaced.
  const [appeared] = useState(() => Date.now());

  return useSyncExternalStore(
    subscribe,
    () => appeared,
    () => reference,
  );
};

export { DAY, HOUR, MINUTE, useDemoClock };

import { DirectionProvider } from "@/registry/erbium/ui/direction";
import { Item, ItemActions, ItemContent, ItemGroup, ItemTitle } from "@/registry/erbium/ui/item";
import { RelativeTimeCard, RelativeTimeProvider } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, MINUTE, useDemoClock } from "../examples/use-demo-clock";

export default function RelativeTimeRtlExample() {
  const now = useDemoClock();

  const events = [
    { name: "دیدگاه تازه", date: now - 5 * MINUTE },
    { name: "ساخت پایان یافت", date: now - 3 * HOUR },
    { name: "مهلت بازبینی", date: now + 4 * DAY },
  ];

  return (
    // The app's direction and language. Pass the same locale to the times.
    <DirectionProvider direction="rtl">
      <RelativeTimeProvider locale="fa-IR">
        <div dir="rtl" lang="fa" className="w-80">
          <ItemGroup>
            {events.map((event) => (
              <Item key={event.name} size="sm">
                <ItemContent>
                  <ItemTitle>{event.name}</ItemTitle>
                </ItemContent>
                <ItemActions>
                  <RelativeTimeCard date={event.date} />
                </ItemActions>
              </Item>
            ))}
          </ItemGroup>
        </div>
      </RelativeTimeProvider>
    </DirectionProvider>
  );
}
